// Auto-generated by service-codegen — RETURNS-38
//
// watch(a, b, c): several method streams in, one stream out. Its item is
// exactly the union of theirs, each tagged by its source:
//
//   const s = watch(tickets.watch(), chats.watch());   // each a MethodStream: it brings its path
//   for await (const it of s) {
//     if ('error' in it) { console.warn(it.source, it.error); continue; }
//     if (it.source === 'chats.watch') { /* it.event is chats.watch's event */ }
//   }
//
// Nothing is new on the wire: each source is the call it already was, and
// closing the merge unsubscribes every subscription still open, once each.

/**
 * A stream that knows its own path — `readonly method` is the method's path
 * as a literal type (`'chats.watch'`): a generated streaming method's
 * `MethodStream` (./rpc, RETURNS-17), or any `AsyncIterable` that says it.
 * A source of this shape is merged with no path written: `watch(a, b, c)`.
 */
export interface MethodSource<P extends string, E> extends AsyncIterable<E> {
  readonly method: P;
}

/**
 * One source of a merge: a {@link MethodSource}, or a `[path, stream]` pair
 * for a stream that does not carry its path.
 */
export type WatchSource<P extends string = string, E = unknown> =
  | MethodSource<P, E>
  | readonly [P, AsyncIterable<E>];

/** One item of a merge: which method spoke, and its event, exactly. */
export interface Tagged<P extends string, E> {
  readonly source: P;
  readonly event: E;
}

/**
 * A source that failed: the error it threw (a `PlexusError` for an error
 * item from the server, a transport `Error` otherwise) and its path. The
 * source has ended; the others go on unless the merge stops on errors.
 */
export interface WatchFailure<P extends string> {
  readonly source: P;
  readonly error: Error;
}

/** The tagged item of one source. Distributes over a union of sources. */
export type TaggedOf<S> =
  S extends readonly [infer P extends string, AsyncIterable<infer E>] ? Tagged<P, E>
  : S extends MethodSource<infer P, infer E> ? Tagged<P, E>
  : never;

/** What a merge of `T` yields: an item of one of its sources, or a failure naming it. */
export type WatchItem<T extends Tagged<string, unknown>> = T | WatchFailure<T['source']>;

/** A merged stream: `for await` it, or `close()` it. */
export interface Merged<T extends Tagged<string, unknown>> extends AsyncIterableIterator<WatchItem<T>> {
  /** Each source's path, in the order given. */
  readonly sources: readonly T['source'][];
  /** End the merge now: every subscription still open is unsubscribed, once. */
  close(): Promise<void>;
}

/** How a merge treats a failing source, and what may end it from outside. */
export interface WatchOptions {
  /** `'continue'` (the default): a failure is an item and the others go on. `'stop'`: it is the last item. */
  readonly errors?: 'continue' | 'stop';
  /** Aborting it closes the merge. */
  readonly signal?: AbortSignal;
}

type Sources = readonly [WatchSource<string, unknown>, ...WatchSource<string, unknown>[]];

/**
 * Merge several method streams into one whose item is exactly the union of
 * theirs, tagged by source. At least one; items in the order they arrive;
 * it ends when every source has ended; a failing source is an item and the
 * others go on. Breaking out of `for await`, `close()`, or an abort
 * unsubscribes every subscription still open.
 */
export function watch<const S extends Sources>(...sources: S): Merged<TaggedOf<S[number]>> {
  return new MergedStream(sources, {}) as unknown as Merged<TaggedOf<S[number]>>;
}

/** {@link watch}, with options: `watchWith({ errors: 'stop' }, a, b)`. */
export function watchWith<const S extends Sources>(options: WatchOptions, ...sources: S): Merged<TaggedOf<S[number]>> {
  return new MergedStream(sources, options) as unknown as Merged<TaggedOf<S[number]>>;
}

// ── Call scopes: how a merge reaches a stream that is waiting ──────────────
//
// An async generator parked on an `await` cannot be returned until that
// await settles — for a quiet watch, never. So a merge starts each source's
// call inside a scope, and the transport reads the scope as the first
// statement of `call()` and registers how to cancel that one subscription
// (send `call_unsub`, wake the parked generator). A transport that does not
// read it still ends on `return()`, after its next item.

/** What a transport registers its cancel with. */
export interface CallScope {
  onCancel(cancel: () => void): void;
}

let activeScope: CallScope | undefined;

/** The scope of the call being started, if a merge is starting it. Read synchronously, first, by a transport's `call()`. */
export function currentCallScope(): CallScope | undefined {
  return activeScope;
}

function within<R>(scope: CallScope, f: () => R): R {
  const previous = activeScope;
  activeScope = scope;
  try {
    return f();
  } finally {
    activeScope = previous;
  }
}

class Scope implements CallScope {
  private cancels: (() => void)[] = [];
  private cancelled = false;
  onCancel(cancel: () => void): void {
    if (this.cancelled) { cancel(); return; }
    this.cancels.push(cancel);
  }
  cancel(): void {
    if (this.cancelled) return;
    this.cancelled = true;
    const cancels = this.cancels;
    this.cancels = [];
    for (const c of cancels) {
      try { c(); } catch { /* a cancel never fails the close */ }
    }
  }
}

// ── The merge ──────────────────────────────────────────────────────────────

/** Every stream given to a merge, so one given twice is refused at the call. */
const watched = new WeakSet<object>();

interface Lane {
  readonly source: string;
  readonly iterable: AsyncIterable<unknown>;
  readonly scope: Scope;
  it: AsyncIterator<unknown> | undefined;
  live: boolean;
  pulling: boolean;
}

type Item = { readonly source: string; readonly event: unknown } | { readonly source: string; readonly error: Error };

function unpack(s: WatchSource<string, unknown>, position: number): [string, AsyncIterable<unknown>] {
  const isIterable = (x: unknown): x is AsyncIterable<unknown> =>
    x !== null && (typeof x === 'object' || typeof x === 'function') &&
    typeof (x as AsyncIterable<unknown>)[Symbol.asyncIterator] === 'function';
  if (Array.isArray(s)) {
    const [path, stream] = s as readonly [unknown, unknown];
    if (typeof path === 'string' && isIterable(stream)) return [path, stream];
  } else if (isIterable(s) && typeof (s as MethodSource<string, unknown>).method === 'string') {
    return [(s as MethodSource<string, unknown>).method, s];
  }
  throw new TypeError(`watch: argument ${position + 1} is neither a MethodStream nor a [path, stream] pair`);
}

function asError(e: unknown): Error {
  return e instanceof Error ? e : new Error(String(e), { cause: e });
}

class MergedStream {
  readonly sources: readonly string[];
  private readonly lanes: Lane[];
  private readonly stopOnError: boolean;
  private readonly ready: { lane: Lane | null; item: Item }[] = [];
  private waiters: ((r: IteratorResult<Item, undefined>) => void)[] = [];
  private started = false;
  /** No more items are taken in: closed, or stopped on an error. */
  private closing = false;
  private ended = false;

  constructor(sources: readonly WatchSource<string, unknown>[], options: WatchOptions) {
    if (sources.length === 0) throw new TypeError('watch: give it at least one stream');
    const seen = new Set<object>();
    this.lanes = sources.map((s, i) => {
      const [source, iterable] = unpack(s, i);
      if (watched.has(iterable) || seen.has(iterable)) {
        throw new TypeError(`watch: the stream given for '${source}' is already being watched`);
      }
      seen.add(iterable);
      return { source, iterable, scope: new Scope(), it: undefined, live: true, pulling: false };
    });
    for (const lane of this.lanes) watched.add(lane.iterable);
    this.sources = this.lanes.map((l) => l.source);
    this.stopOnError = options.errors === 'stop';
    const signal = options.signal;
    if (signal) {
      if (signal.aborted) this.finish();
      else signal.addEventListener('abort', () => this.finish(), { once: true });
    }
  }

  [Symbol.asyncIterator](): this {
    return this;
  }

  next(): Promise<IteratorResult<Item, undefined>> {
    if (!this.started && !this.ended) {
      this.started = true;
      for (const lane of this.lanes) this.pull(lane);
    }
    const head = this.ready.shift();
    if (head) {
      if (head.lane) this.pull(head.lane);
      return Promise.resolve({ value: head.item, done: false });
    }
    if (this.ended || this.closing || !this.lanes.some((l) => l.live)) {
      this.finish();
      return Promise.resolve({ value: undefined, done: true });
    }
    return new Promise((resolve) => this.waiters.push(resolve));
  }

  return(): Promise<IteratorResult<Item, undefined>> {
    this.finish();
    return Promise.resolve({ value: undefined, done: true });
  }

  close(): Promise<void> {
    this.finish();
    return Promise.resolve();
  }

  /** Ask one source for its next item; at most one outstanding per source. */
  private pull(lane: Lane): void {
    if (!lane.live || lane.pulling || this.closing) return;
    lane.pulling = true;
    let next: Promise<IteratorResult<unknown>>;
    try {
      next = within(lane.scope, () => {
        lane.it ??= lane.iterable[Symbol.asyncIterator]();
        return lane.it.next();
      });
    } catch (e) {
      next = Promise.reject(e);
    }
    next.then(
      (r) => {
        lane.pulling = false;
        if (this.closing) return;
        if (r.done) {
          lane.live = false;
          this.settle();
        } else {
          this.deliver(lane, { source: lane.source, event: r.value });
        }
      },
      (e: unknown) => {
        lane.pulling = false;
        lane.live = false;
        if (this.closing) return;
        this.deliver(null, { source: lane.source, error: asError(e) });
        if (this.stopOnError) {
          // The failure is the last item: everything else goes now.
          this.closing = true;
          this.cancelLanes();
          this.settle();
        } else {
          this.settle();
        }
      },
    );
  }

  /** Hand an item to a waiting reader (and ask its source for the next), or queue it. */
  private deliver(lane: Lane | null, item: Item): void {
    const waiter = this.waiters.shift();
    if (waiter) {
      waiter({ value: item, done: false });
      if (lane) this.pull(lane);
    } else {
      this.ready.push({ lane, item });
    }
  }

  /** End the readers that are waiting, when nothing more can come. */
  private settle(): void {
    if (this.ready.length > 0) return;
    if (!this.closing && this.lanes.some((l) => l.live)) return;
    this.finish();
  }

  private cancelLanes(): void {
    for (const lane of this.lanes) {
      if (!lane.live) continue;
      lane.live = false;
      lane.scope.cancel();
      const it = lane.it;
      if (it && typeof it.return === 'function') {
        // Not awaited: a source parked on an await returns once its scope's
        // cancel has woken it (or after its next item, if its transport
        // does not read the scope).
        Promise.resolve()
          .then(() => it.return!())
          .catch(() => { /* a source that throws on return has still ended */ });
      }
    }
  }

  /** Close: unsubscribe what is open, drop what is queued, end every reader. */
  private finish(): void {
    if (this.ended) return;
    this.ended = true;
    this.closing = true;
    this.cancelLanes();
    this.ready.length = 0;
    const waiters = this.waiters;
    this.waiters = [];
    for (const w of waiters) w({ value: undefined, done: true });
  }
}
